import{_ as e,c as i,o as l,af as r}from"./chunks/framework.QPFNXNt9.js";const m=JSON.parse('{"title":"PetLoss — 隐私政策","description":"PetLoss 隐私政策：一款私密、离线的宠物纪念与哀伤支持 App。","frontmatter":{"title":"PetLoss — 隐私政策","description":"PetLoss 隐私政策：一款私密、离线的宠物纪念与哀伤支持 App。"},"headers":[],"relativePath":"zh/privacy.md","filePath":"zh/privacy.md"}'),t={name:"zh/privacy.md"};function h(o,a,s,n,p,d){return l(),i("div",null,[...a[0]||(a[0]=[r('<h1 id="petloss-—-隐私政策" tabindex="-1">PetLoss — 隐私政策 <a class="header-anchor" href="#petloss-—-隐私政策" aria-label="Permalink to “PetLoss — 隐私政策”">​</a></h1><p>最后更新：2025-01-18</p><p>PetLoss 是一款为宠物离世提供纪念与陪伴的私密离线应用。本政策说明应用如何处理数据及其用途。</p><h2 id="概要" tabindex="-1">概要 <a class="header-anchor" href="#概要" aria-label="Permalink to “概要”">​</a></h2><ul><li>无账号、无登录。</li><li>无广告、无统计 SDK、无第三方追踪。</li><li>你的纪念项目与日记仅保存在设备本地。</li><li>仅在你选择导入或保存时访问照片。</li><li>网络仅用于 App Store 购买/恢复，或你打开外部链接/发送邮件时使用。</li></ul><h2 id="我们在设备本地保存的数据" tabindex="-1">我们在设备本地保存的数据 <a class="header-anchor" href="#我们在设备本地保存的数据" aria-label="Permalink to “我们在设备本地保存的数据”">​</a></h2><p>为提供核心功能，我们会在本地保存：</p><ul><li>纪念项目（宠物名、日期、备注）、模板与设置。</li><li>导入的照片与生成的导出内容。</li><li>日记与引导记录。</li><li>购买状态（Pro 权限）本地缓存。</li><li>提醒通知偏好（如你开启）。</li></ul><p>你可以在应用内删除项目，或通过删除应用清除全部数据。</p><h2 id="照片与文件" tabindex="-1">照片与文件 <a class="header-anchor" href="#照片与文件" aria-label="Permalink to “照片与文件”">​</a></h2><p>PetLoss 仅在你选择导入或保存媒体时请求照片权限。所选照片会拷贝到应用沙盒中以离线使用。备份与导出只会在你选择位置时保存到文件。</p><h2 id="应用内购买" tabindex="-1">应用内购买 <a class="header-anchor" href="#应用内购买" aria-label="Permalink to “应用内购买”">​</a></h2><p>购买由 Apple 通过 StoreKit 处理，我们不会收到你的支付信息。Apple 可能会根据其政策处理购买记录。</p><h2 id="我们不收集的内容" tabindex="-1">我们不收集的内容 <a class="header-anchor" href="#我们不收集的内容" aria-label="Permalink to “我们不收集的内容”">​</a></h2><ul><li>不收集个人标识信息（姓名、邮箱、电话、精确位置）。</li><li>不访问通讯录、相机、麦克风或日历。</li><li>不使用广告标识符或行为追踪。</li></ul><h2 id="可选的邮件支持" tabindex="-1">可选的邮件支持 <a class="header-anchor" href="#可选的邮件支持" aria-label="Permalink to “可选的邮件支持”">​</a></h2><p>如需支持，请发送邮件至 <a href="mailto:lidonghui11911@gmail.com" target="_blank" rel="noreferrer">lidonghui11911@gmail.com</a>。邮件由你的邮箱应用发送，你可自行决定分享内容。</p><h2 id="儿童隐私" tabindex="-1">儿童隐私 <a class="header-anchor" href="#儿童隐私" aria-label="Permalink to “儿童隐私”">​</a></h2><p>应用分级为 4+。我们不会主动收集儿童的个人信息。</p><h2 id="安全" tabindex="-1">安全 <a class="header-anchor" href="#安全" aria-label="Permalink to “安全”">​</a></h2><p>你的数据存放在 iOS 沙盒中。请保持系统更新并保护好设备。</p><h2 id="政策更新" tabindex="-1">政策更新 <a class="header-anchor" href="#政策更新" aria-label="Permalink to “政策更新”">​</a></h2><p>我们可能会更新本政策，并在本页顶部更新日期。</p><h2 id="联系" tabindex="-1">联系 <a class="header-anchor" href="#联系" aria-label="Permalink to “联系”">​</a></h2><p>如对隐私或本应用有疑问，请发送邮件至：lidonghui11911@gmail.com</p>',25)])])}const P=e(t,[["render",h]]);export{m as __pageData,P as default};
